10	var screenW = 0
11	var screenH = 0
12	var shapeCache = null
13	
14	function detectShape() {
15	  try {
16	    var info = undefined
17	    if (typeof globalThis !== "undefined" && globalThis.systemInfo) {
18	      info = globalThis.systemInfo
19	    } else if (typeof global !== "undefined" && global.systemInfo) {
20	      info = global.systemInfo
21	    }
22	    if (info) {
23	      screenW = info.screenWidth || 466
24	      screenH = info.screenHeight || 466
25	    } else {
26	      screenW = 466
27	      screenH = 466
28	    }
29	  } catch (e) {
30	    screenW = 466
31	    screenH = 466
32	  }
33	
34	  // 宽高比接近 1:1 判定为圆形
35	  var ratio = screenW / screenH
36	  var isRound = ratio > 0.9 && ratio < 1.1
37	
38	  shapeCache = {
39	    isRound: isRound,
40	    isSquare: !isRound,
41	    screenWidth: screenW,
42	    screenHeight: screenH,
43	    radius: Math.round(screenW / 2)
44	  }
45	  return shapeCache
46	}
47	
48	// ─── 形状检测 ──────────────────────────────────────────
49	
50	export function getScreenShape() {
51	  if (!shapeCache) { detectShape() }
52	  return shapeCache
53	}
54	
55	export function getScreenHeight() {
56	  return getScreenShape().screenHeight
57	}
58	
59	export function getScreenWidth() {
60	  return getScreenShape().screenWidth
61	}
62	
63	// ─── Apple Watch 风格安全区内边距 ──────────────────────
64	
65	export function getSafePadding() {
66	  var shape = getScreenShape()
67	  if (shape.isRound) {
68	    // Apple Watch 风格：更精确的圆形安全区
69	    var radius = shape.radius
70	    return {
71	      top: Math.round(radius * 0.18),    // 18%
72	      bottom: Math.round(radius * 0.18),
73	      left: Math.round(radius * 0.22),   // 22%（水平更宽）
74	      right: Math.round(radius * 0.22)
75	    }
76	  }
77	  return { top: 16, right: 18, bottom: 16, left: 18 }
78	}
79	
80	// ─── 内容 padding ──────────────────────────────────────
81	
82	export function getContentPadding() {
83	  var p = getSafePadding()
84	  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
85	}
86	
87	// ─── Apple Watch 风格圆角 ──────────────────────────────
88	
89	export function getCardRadius() {
